INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000898', 'Benarkah surfaktan bekerja dengan mengubah wettability batuan dan menurunkan IFT sekaligus?', 'Is it true that surfactants work by altering rock wettability and reducing IFT at the same time?', 'yesorno', 'PFC000000010', 'Final Advanced', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'Yes', 'Yes', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
INSERT INTO final_exam (id, question, question_en, type, lid, excerpt, options, options_en, image, correct_option, correct_option_en, created, updated) VALUES ('FQT00000000009200000899', 'Benarkah alkali selalu meningkatkan viskositas larutan secara signifikan?', 'Is it true that alkali always significantly increases solution viscosity?', 'yesorno', 'PFC000000010', 'Final Advanced', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', 'a:2:{i:0;s:3:"Yes";i:1;s:2:"No";}', '', 'No', 'No', '2026-10-21 10:00:00', '2026-10-21 10:00:00');
